def is_single_quoted_literal(s):
    if len(s) < 2:
        return False
    if s[0] != "'" or s[-1] != "'":
        return False
    inner = s[1:-1]
    i = 0
    n = len(inner)
    while i < n:
        c = inner[i]
        if c == '\\':
            if i + 1 >= n:
                return False
            nxt = inner[i + 1]
            if nxt != '\\' and nxt != "'":
                return False
            i += 2
        elif c == "'":
            return False
        else:
            i += 1
    return True

