    for tok in tokens:
        m_self = re.fullmatch(r'<([a-z]+)/>', tok)
        m_open = re.fullmatch(r'<([a-z]+)>', tok)
        m_close = re.fullmatch(r'</([a-z]+)>', tok)
        if m_self:
            continue
        elif m_open:
            stack.append(m_open.group(1))
        elif m_close:
            word = m_close.group(1)
            if not stack or stack[-1] != word:
                return False
            stack.pop()
        else:
            return False
    return len(stack) == 0

